
const sb=window.supabase.createClient('https://xcgbxurbnsytecrdupct.supabase.co','sb_publishable_PAd7gf0Q-N9H4PqgqqaVNg_EfE583xO');
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const coach=document.body.dataset.supportRole==='trainer';let cases=[],me=null,busy=false,createId=null;
function message(s){$('supportMessage').textContent=s;}
async function rpc(action,target=null,payload=null,revision=null){const {data,error}=await sb.rpc('momentum_support',{action,target,payload,expected_revision:revision});if(error)throw error;return data;}
async function account(){const {data,error}=await sb.auth.getUser();if(error||!data.user){location.replace('test.html');throw Error('Please sign in.');}const p=await sb.from('profiles').select('id,full_name,role').eq('id',data.user.id).single();if(p.error)throw p.error;if(p.data.role!==(coach?'trainer':'athlete')){location.replace(p.data.role==='trainer'?'test4.html':'test3.html');throw Error('Wrong account role.');}if(me&&me!==p.data.id){cases=[];render();throw Error('Account changed. Reload this page.');}me=p.data.id;return {...p.data,email:data.user.email};}
function render(){
 const root=$(coach?'list':'reportList');if(coach){$('total').textContent=cases.length;$('open').textContent=cases.filter(c=>c.status!=='Resolved').length;$('resolved').textContent=cases.filter(c=>c.status==='Resolved').length;}else $('reportCount').textContent=cases.length;
 const f=coach?$('filter').value:'all',q=coach?$('search').value.toLowerCase():'';
 const rows=cases.filter(c=>(f==='all'||c.status===f)&&[c.subject,c.description,c.athlete_name,c.id].join(' ').toLowerCase().includes(q));
 root.innerHTML=rows.map(c=>`<article class="${coach?'item':'report-card'}" style="display:block;overflow-wrap:anywhere"><h3>${esc(c.subject)}</h3><p class="${coach?'':'report-description'}">${coach?esc(c.athlete_name)+' · ':''}${esc(c.created_at.slice(0,10))} · ${esc(c.category)} · ${esc(c.priority)}<br>${esc(c.description)}</p><span class="${coach?'badge':'report-status'}">${esc(c.status)}</span><div style="margin-top:12px">${c.replies.map(r=>`<p style="padding:10px;border-left:2px solid #39d98a;white-space:pre-wrap"><b>${r.role==='trainer'?'Coach':'Athlete'}</b> · ${esc(r.created_at.slice(0,16))}<br>${esc(r.body)}</p>`).join('')}</div><textarea data-body="${c.id}" maxlength="1500" placeholder="Write a reply..." style="width:100%;padding:10px;color:inherit;background:transparent;border:1px solid #52605c;border-radius:8px"></textarea><div class="actions" style="margin-top:10px"><button type="button" class="${coach?'btn':'reset-btn'}" data-reply="${c.id}">Send reply</button>${coach?`<select class="btn" data-status="${c.id}">${['Open','In Review','Resolved'].map(s=>`<option ${c.status===s?'selected':''}>${s}</option>`).join('')}</select>`:''}<button type="button" class="${coach?'btn':'reset-btn'}" data-archive="${c.id}">Archive</button></div></article>`).join('')||'<div class="empty-state">No complaints to display.</div>';
 root.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>mutate('reply',b.dataset.reply,{body:root.querySelector(`[data-body="${b.dataset.reply}"]`).value}));
 root.querySelectorAll('[data-status]').forEach(b=>b.onchange=()=>mutate('status',b.dataset.status,{status:b.value}));root.querySelectorAll('[data-archive]').forEach(b=>b.onclick=()=>{if(confirm('Archive for you? The other person keeps their copy.'))mutate('archive',b.dataset.archive);});
}
async function refresh(){await account();cases=await rpc('list');render();}
async function mutate(action,id,payload){if(busy)return;busy=true;document.querySelectorAll('[data-reply],[data-status],[data-archive]').forEach(b=>b.disabled=true);try{await account();await rpc(action,id,payload,cases.find(c=>c.id===id)?.revision);await refresh();message('Saved to Supabase.');}catch(e){message(e.message+' Refresh before retrying if the case changed.');}finally{busy=false;document.querySelectorAll('[data-reply],[data-status],[data-archive]').forEach(b=>b.disabled=false);}}
async function create(event){event?.preventDefault();if(busy)return;busy=true;const button=coach?$('save'):$('reportForm').querySelector('[type="submit"]');button.disabled=true;try{await account();createId??=crypto.randomUUID();const payload=coach?{id:createId,subject:$('subject').value.trim(),description:$('details').value.trim(),category:'Trainer / Coaching',priority:'Low'}:{id:createId,subject:$('subject').value.trim(),description:$('description').value.trim(),category:$('category').value,priority:document.querySelector('[name="priority"]:checked')?.value||'Low',contact_email:$('contactEmail').value.trim()};await rpc('create',coach?$('athlete').value:null,payload);createId=null;if(coach){$('modal').style.display='none';$('subject').value=$('details').value='';}else{$('reportForm').reset();$('characterCount').textContent='0';}message('Sent to the connected coach and saved to Supabase.');await refresh();}catch(e){message(e.message);}finally{busy=false;button.disabled=false;}}
async function logout(){try{const {error}=await sb.auth.signOut();if(error)throw error;location.href='test.html';}catch(e){message(e.message);}}
async function init(){try{const p=await account();if(coach){const {data,error}=await sb.rpc('momentum_coaching',{action:'inbox'});if(error)throw error;$('athlete').innerHTML='<option value="">Choose connected athlete...</option>'+data.filter(a=>a.status==='accepted').map(a=>`<option value="${a.id}">${esc(a.name)} — ${a.id}</option>`).join('');}else{$('athleteName').textContent=p.full_name;$('athleteId').textContent=p.id;$('avatar').textContent=(p.full_name||'A')[0];$('contactEmail').value=p.email||'';}await refresh();message('Messages are private to you and your connected coach. Archive hides your copy; a new reply restores it.');}catch(e){message(e.message);} }
if(coach){$('newComplaint').onclick=()=>$('modal').style.display='block';$('cancel').onclick=()=>$('modal').style.display='none';$('save').onclick=create;$('filter').onchange=render;$('search').oninput=render;$('logoutBtn').onclick=e=>{e.preventDefault();logout();};}else{$('reportForm').onsubmit=create;$('description').oninput=e=>$('characterCount').textContent=e.target.value.length;}
$('refreshSupport').onclick=()=>{if(!busy)refresh().then(()=>message('Updated.')).catch(e=>message(e.message));};init();

sb.auth.onAuthStateChange?.((event,session)=>{if(me&&session?.user?.id!==me){cases=[];render();message('Account changed. Reload or sign in again.');}});

